import React, { useEffect } from "react";
import DataTable from "react-data-table-component";
import { FaEye, FaEdit } from "react-icons/fa";
import { Button, Modal, Form, Spinner } from "react-bootstrap";
import "react-toastify/dist/ReactToastify.css";
import "../../../src/App.css";
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { CKEditor } from "@ckeditor/ckeditor5-react";
import ClassicEditor from "@ckeditor/ckeditor5-build-classic";
import { ToastContainer, toast } from 'react-toastify';
// import { toast } from "react-toastify";
import { makeApiRequest } from "../../axiosService/ApiCall";
import axios from "axios";

function TermsConditons() {
  const [Title, setTitle] = useState("");
  // console.log("Title", Title);
  const [TermsContent, setTermsContent] = useState("");
  // console.log("TermsContent", TermsContent);
  const [totalData, setTotalData] = useState([]);
  const [editId, setEditId] = useState(null);
  // console.log("editId", editId);
  const [show, setShow] = useState(false);
  // console.log("show", show);
  const [termError, setTermError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [perPage, setPerPage] = useState(10);
  const [currentPage, setCurrentPage] = useState(1);
  const navigate = useNavigate();
  const [TermsEdit, setTermsEdit] = useState(0);
  // console.log("TermsEdit", TermsEdit);
  const [adminType, setAdminType] = useState("");

  const handleClose = () => setShow(false);

  const handleShow = (row) => {
    // if (TermsEdit == 1) {
    //   toast.warning(
    //     "Access Denied: You are not allowed to edit TermsConditons details."
    //   );
    // }

    setTitle(row.Title);
    setTermsContent(row.TermsContent);
    setEditId(row._id);
    setShow(true);
  };
  // ...................edit data
  const handleUpdate = async (event) => {
    event.preventDefault();

    const validationErrors = {};
    if (!Title) validationErrors.Title = "*Title is required";
    if (!TermsContent)
      validationErrors.TermsContent = "*TermsContent is required";
    setTermError(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;

    try {
      setIsLoading(true);
      const address = await axios.get("https://api.ipify.org/?format=json");

      const lastloginIpAddress = address.data.ip;
      const ip = lastloginIpAddress
      const payload = { Title, TermsContent, ip };

      const editData = await makeApiRequest({
        url: `edit-termsPage/${editId}  `,
        method: "PUT",
        data: payload,
      });
      // console.log("editData", editData);

      if (editData.status === true) {
        toast.success(editData.message);
        setTitle("");
        setTermsContent("");
        setEditId(null);
        getTermsPage(); // refresh after update
        setShow(false);
      } else {
        toast.warn(editData.message);
      }
    } catch (error) {
      console.error("Error updating:", error);
      toast.error("Something went wrong");
    } finally {
      setIsLoading(false);
    }
  };
  // ...................edit data finshesd ..................
  useEffect(() => {
    getTermsPage();
  }, []);
  // get the terms and conditions page data

  const getTermsPage = async () => {
    try {
      let params = {
        url: `/get-TermspageData`,
        method: "GET",
      };
      let getTermsPageData = await makeApiRequest(params);
      // console.log("getTermsPageData", getTermsPageData);

      if (getTermsPageData.status == true) {
        const getTotalData = getTermsPageData.data;
        setTotalData(getTotalData);
      } else {
        toast.warn(`${getTermsPageData.message}`);
      }
    } catch (error) {
      console.log("getTermsPage error", error);
      toast.warn(`Something went wrong`);
    }
  };

  const columnsData = [
    {
      name: "S.No",
      cell: (row, index) => (currentPage - 1) * perPage + index + 1,
      sortable: true,
      width: "100px",
    },
    {
      name: "Title",
      selector: (row) => row.Title,
      sortable: true,
      width: "240px",
    },

    {
      name: "Edit",
      selector: (row) => (
        <div key={row._id} className="d-flex justify-content-center">
          <FaEdit
            style={{ cursor: "pointer" }}
            onClick={() => handleShow(row)}
            className="copy-icon"
          />
        </div>
      ),
    },
  ];
  const editorConfig = {
    // toolbar: [
    //   "heading",
    //   "|",
    //   "bold",
    //   "italic",
    //   "Link",
    //   "codeBlock",
    //   "|",
    //   "bulletedList",
    //   "numberedList",
    //   "|",
    //   "undo",
    //   "redo",
    //   "|",
    //   "fontFamily",
    //   "fontSize",
    //   "removeFormat",
    // ], 

toolbar: [
  "heading",
  "bold",
  "italic",
  "link",
  "bulletedList",
  "numberedList",
  "undo",
  "redo"
],

    fontFamily: {
      options: [
        "default",
        "Arial, Helvetica, sans-serif",
        "Courier New, Courier, monospace",
        "Georgia, serif",
        "Lucida Sans Unicode, Lucida Grande, sans-serif",
        "Tahoma, Geneva, sans-serif",
        "Times New Roman, Times, serif",
        "Trebuchet MS, Helvetica, sans-serif",
        "Verdana, Geneva, sans-serif",
      ],
    },
    fontSize: {
      options: [9, 11, 13, "default", 17, 19, 21],
    },
    link: {
      decorators: {
        addTargetToExternalLinks: {
          mode: "automatic",
          callback: (url) => {
            if (/^(https?:)?\/\//i.test(url)) {
              return true;
            }

            if (/^[a-z0-9.-]+\.(com|net|org|in|co|io|ai)(\/.*)?$/i.test(url)) {
              return true;
            }
            return false;
          },

          attributes: {
            target: "_blank",
            rel: "noopener noreferrer",
          },
        },
      },
    },
  };
  // console.log("config-1", editorConfig.toolbar);
  // subamin edit access function
  useEffect(() => {
    termsConditonsRes();
  }, []);
  const termsConditonsRes = async () => {
    try {
      let params = {
        url: "view-edit-GetData",
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      const termsConditonsRes = await makeApiRequest(params);
      // console.log("termsConditonsRes", termsConditonsRes);
      if (termsConditonsRes.status) {
        const response = termsConditonsRes.data;
        // console.log("response--", response);
        setTermsEdit(response?.adminPermissions?.cms?.Edit);
        setAdminType(response?.admin_type);
      }
    } catch (error) {
      console.log("err--", error);
      // toast(termsConditonsRes.message);
      // toast("Something Went Wrong...");
    }
  };

  return (
    <div className="App">
      <ToastContainer />
      <div className="container-fluid">
        <div className=" text-dark">
          <div className="row">
            <div className="col-sm-12">
              <div className="py-3 justify-content-center d-flex justify-content-between">
                <h5 className="component-user  ms-lg-0">{}</h5>
              </div>
              {/* create the ck editor  */}

              {/* create the ck editor finsihed  */}
              <div className="custom-inside-saled-order text-center mt-0">
                <div className="liquidity-table-1">
                  <DataTable
                    columns={columnsData}
                    data={totalData}
                    pagination
                    paginationPerPage={perPage}
                    onChangeRowsPerPage={(newPerPage, page) => {
                      setPerPage(newPerPage);
                      setCurrentPage(page);
                    }}
                    onChangePage={(page) => {
                      setCurrentPage(page);
                    }}
                    paginationRowsPerPageOptions={[10, 20]}
                    persistTableHead
                    progressComponent={
                      <div className="text center py-4 w-100">
                        <Spinner animation="border" />
                      </div>
                    }
                    noDataComponent={<div className="text-center">No Data</div>}
                  />
                </div>
              </div>
            </div>
          </div>

          <Modal
            show={show}
            onHide={handleClose}
            size="lg"
            enforceFocus={false}
            autoFocus={false}
          >
            <Modal.Header closeButton>
              <Modal.Title>Edit Terms</Modal.Title>
            </Modal.Header>
            <Modal.Body>
              <Form>
                <Form.Group>
                  <Form.Label>Title</Form.Label>
                  <Form.Control
                    type="text"
                    value={Title}
                    onChange={(e) => setTitle(e.target.value)}
                    placeholder="Enter title"
                    disabled={TermsEdit == 0 && adminType == "SubAdmin"}
                  />
                  {termError.Title && (
                    <div className="text-danger">{termError.Title}</div>
                  )}
                </Form.Group>

                <Form.Group className="mt-3">
                  <Form.Label>Content</Form.Label>
                  {}

                  <CKEditor
                    editor={ClassicEditor}
                    data={TermsContent || ""}
                    onReady={(editor) => {
                      setTimeout(() => {
                        const panels = document.querySelectorAll(
                          ".ck.ck-balloon-panel"
                        );
                        panels.forEach((panel) => {
                          panel.style.zIndex = "9999";
                        });
                      }, 200);

                      // console.log("Editor is ready", editor);
                    }}
                    // onChange={(event, editor) => {
                    //   console.log("event--", event);
                    //   console.log("editor--", editor);
                    //   try {
                    //     const data =
                    //       editor?.getData?.()?.replace(/�/g, "") || "";

                    //     console.log("data--", data);
                    //     setTermsContent(data);
                    //   } catch (err) {
                    //     console.error("Editor error", err);
                    //   }
                    // }}
                    onChange={(event, editor) => {
                      let data = editor.getData()?.replace(/�/g, "") || "";

                      data = data.replace(
                        /href="(?!https?:\/\/)([a-z0-9.-]+\.(com|net|org|in|co|io|ai)(\/[^"]*)?)"/gi,
                        'href="https://$1"'
                      );

                      setTermsContent(data);
                    }}
                    config={{
                      ...editorConfig,
                      readOnly: TermsEdit == 0, 
                    }}
                  />

                  {termError.TermsContent && (
                    <div className="text-danger">{termError.TermsContent}</div>
                  )}
                </Form.Group>

                <div className="text-end mt-4">
                  <Button
                    variant="secondary"
                    onClick={handleClose}
                    className="me-2"
                  >
                    Cancel
                  </Button>

                  <Button
                    className="custom-nav-button-1 active"
                    onClick={(event) => {
                      if (TermsEdit == 0 && adminType == "SubAdmin" ) {
                        toast.warning("access denied");
                        return; // Submit prevent
                      }
                      handleUpdate(event);
                    }}
                    disabled={TermsEdit == 0 && adminType == "SubAdmin"}
                  >
                    {isLoading ? (
                      <Spinner animation="border" size="sm" />
                    ) : (
                      "Update"
                    )}
                  </Button>
                </div>
              </Form>
            </Modal.Body>
          </Modal>
        </div>
      </div>
    </div>
  );
}

export default TermsConditons;
